package dev.redstoneengineering.block;import com.mojang.serialization.MapCodec;import dev.redstoneengineering.*;import dev.redstoneengineering.physics.VibrationNetwork;import dev.redstoneengineering.physics.InformationRuntime;import net.minecraft.core.*;import net.minecraft.network.chat.Component;import net.minecraft.world.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.util.RandomSource;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.BlockHitResult;public class MechanicalVibrationReceiverBlock extends PassiveDirectionalSignalBlock{public MechanicalVibrationReceiverBlock(Properties p){super(p);}@Override public MapCodec<MechanicalVibrationReceiverBlock> codec(){return RedstoneEngineering.MECHANICAL_VIBRATION_RECEIVER_CODEC.value();}@Override protected int computeOutput(Level l,BlockPos p,BlockState s){return Math.min(15,VibrationNetwork.sample(l,p).amplitude());}@Override protected void onPlace(BlockState s,Level l,BlockPos p,BlockState o,boolean m){super.onPlace(s,l,p,o,m);if(l instanceof ServerLevel sl)sl.scheduleTick(p,this,4);}@Override protected void tick(BlockState s,ServerLevel l,BlockPos p,RandomSource r){int v=InformationRuntime.value(l,"mech_wave",p);if(v>0)InformationRuntime.write(l,"mech_wave",p,Math.max(0,v-2),InformationRuntime.aux(l,"mech_wave",p),v>2,Math.max(0,InformationRuntime.quality(l,"mech_wave",p)-5));updateOutput(l,p,s,outputValue(l,p,s));l.scheduleTick(p,this,4);}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide){var w=VibrationNetwork.sample(l,p);pl.displayClientMessage(Component.literal("Mechanical wave A="+w.amplitude()+" f="+w.frequency()+" valid="+w.valid()),true);}return InteractionResult.sidedSuccess(l.isClientSide);}}